Here's a C++ program that uses a recursive function to generate the Fibonacci sequence, starting with two given integers as the first two sequence elements. The program prompts the user to input the first two integers, and also the number of sequence elements to generate. The program then outputs the generated sequence, with each element separated by a comma and a space. The program also includes error handling for invalid inputs, such as non-numeric inputs or negative numbers.

```cpp
#include <iostream>
#include <string>
#include <sstream>

using namespace std;

int fibonacci(int n, int a, int b) {
    if (n == 0) {
        return a;
    } else {
        return fibonacci(n - 1, b, a + b);
    }
}

int main() {
    string input;
    int num1, num2, seq_length;

    cout << "Enter the first two integers: ";
    getline(cin, input);

    istringstream iss(input);
    iss >> num1 >> num2;

    if (iss.fail() || num1 < 0 || num2 < 0) {
        cout << "Invalid input. Please enter valid integers." << endl;
        return 1;
    }

    cout << "Enter the number of sequence elements to generate: ";
    cin >> seq_length;

    if (seq_length <= 0) {
        cout << "Invalid input. Please enter a positive integer." << endl;
        return 1;
    }

    int sequence[seq_length];
    sequence[0] = num1;
    sequence[1] = num2;

    for (int i = 2; i < seq_length; i++) {
        sequence[i] = fibonacci(i, num1, num2);
    }

    cout << "Fibonacci sequence: ";
    for (int i = 0; i < seq_length; i++) {
        cout << sequence[i] << ", ";
    }
    cout << endl;

    return 0;
}
```

