Here's a React Hooks-based component that allows you to convert between different temperature units:

```javascript
import React, { useState } from 'react';

const TemperatureConverter = () => {
  const [temperature, setTemperature] = useState(null);
  const [unit, setUnit] = useState('C');
  const [convertedTemperature, setConvertedTemperature] = useState(null);

  const handleInputChange = (event) => {
    setTemperature(parseFloat(event.target.value));
  };

  const handleUnitChange = (event) => {
    setUnit(event.target.value);
  };

  const convertTemperature = () => {
    if (!temperature || !unit) return;

    let convertedValue = null;

    switch (unit) {
      case 'C':
        convertedValue = (temperature * 9 / 5) + 32;
        break;
      case 'F':
        convertedValue = (temperature - 32) * 5 / 9;
        break;
      case 'K':
        convertedValue = temperature - 273.15;
        break;
      default:
        return;
    }

    setConvertedTemperature(convertedValue.toFixed(2));
  };

  return (
    <div>
      <label htmlFor="temperature">Enter the temperature:</label>
      <input type="number" id="temperature" value={temperature} onChange={handleInputChange} />

      <label htmlFor="unit">Select the input unit:</label>
      <select id="unit" value={unit} onChange={handleUnitChange}>
        <option value="C">Celsius</option>
        <option value="F">Fahrenheit</option>
        <option value="K">Kelvin</option>
      </select>

      <button onClick={convertTemperature}>Convert</button>

      {convertedTemperature && (
        <p>The converted temperature is {convertedTemperature} {unit}.</p>
      )}
    </div>
  );
};

export default Temperature

