Here's a Go program that parses a struct in a Go source file and generates an Avro schema from it:

```go
package main

import (
	"fmt"
	"os"
	"reflect"
	"strings"

	"github.com/apache/avro/v2/schema"
)

func main() {
	if len(os.Args) != 3 {
		fmt.Println("Usage: ./generate_avro_schema <go_source_file> <struct_name>")
		os.Exit(1)
	}

	goSourceFile := os.Args[1]
	structName := os.Args[2]

	// Read the Go source file
	content, err := os.ReadFile(goSourceFile)
	if err != nil {
		fmt.Println(err)
		os.Exit(1)
	}

	// Parse the Go source file for the specified struct
	structType := reflect.TypeOf(reflect.New(reflect.Struct).Elem())
	for _, field := range structType.Fields() {
		if field.Name == structName {
			break
		}
	}
	if field.Name == "" {
		fmt.Printf("Error: Could not find struct %s in %s\n", structName, goSourceFile)
		os.Exit(1)
	}

	// Generate the Avro schema
	avroSchema := schema.NewSchemaBuilder().
		SetName(structName).
		AddField(field.Name, field.Type.String()).
		Build()

	// Write the Avro schema to a file
	err = os.WriteFile("struct.avsc", avroSchema.String(), os.ModePerm)
	if err != nil {
		fmt.Println(err)
		os.Exit(1)
	}

	fmt.Printf("Avro schema generated for %s in %s\n", structName, goSourceFile)
}
```

To use this program, save it as `generate_avro_schema.go` and run it with the name of the Go source file

Here's an HTML page with a button that displays the background image of the user's computer on the desktop:

```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Display Background Image</title>
    <style>
        body {
            text-align: center;
        }

        button {
            background-color: #4CAF50;
            color: white;
            padding: 10px 20px;
            border: none;
            cursor: pointer;
        }

        button:hover {
            background-color: #45a049;
        }
    </style>
</head>
<body>
    <button onclick="displayBackgroundImage()">Display Background Image</button>
    <script>
        function displayBackgroundImage() {
            const backgroundImage = document.createElement('img');
            backgroundImage.src = chrome.extension.getURL('background.jpg');
            backgroundImage.style.position = 'absolute';
            backgroundImage.style.top = '0';
            backgroundImage.style.left = '0';
            backgroundImage.style.width = '100%';
            backgroundImage.style.height = '100%';
            document.body.appendChild(backgroundImage);
        }
    </script>
</body>
</html>
```

Make sure you have a `background.jpg` image in your Chrome extension's `assets` folder. Also, replace the `chrome.extension.getURL('background.jpg')` with the actual path to your background image.

