To create a simple toast notification using React Context, follow these steps:

1. Create a `NotificationContext` file:

```javascript
import React, { createContext, useReducer } from 'react';

const initialState = {
  notifications: [],
};

const notificationReducer = (state, action) => {
  switch (action.type) {
    case 'ADD_NOTIFICATION':
      return { ...state, notifications: [...state.notifications, action.notification] };
    case 'REMOVE_NOTIFICATION':
      return { ...state, notifications: state.notifications.filter((n) => n.id !== action.id) };
    default:
      return state;
  }
};

export const NotificationContext = createContext(initialState);

export function NotificationProvider({ children }) {
  const [state, dispatch] = useReducer(notificationReducer, initialState);

  const addNotification = (notification) => {
    dispatch({ type: 'ADD_NOTIFICATION', notification });
  };

  const removeNotification = (id) => {
    dispatch({ type: 'REMOVE_NOTIFICATION', id });
  };

  return (
    <NotificationContext.Provider value={{ notifications: state.notifications, addNotification, removeNotification }}>
      {children}
    </NotificationContext.Provider>
  );
}
```

2. Create a `Notification` component:

```javascript
import React, { useContext } from 'react';
import { NotificationContext } from './NotificationContext';

const Notification = ({ notification }) => {
  const { notifications, addNotification, removeNotification } = useContext(NotificationContext);

  const handleClose = () => {
    removeNotification(notification.id);
  };

  return (
    <div className="notification">
      <p>{notification.message}</p>
      <button onClick={handleClose}>Close</button>
    </div>
  );
};

export default Notification;
```

