        return " ".join(reversed(words))

def scientific_notation_to_word(num_str):
    match = re.match(r'(\d+)\.?(\d*)e(\+|\-)?(\d+)', num_str)
    if not match:
        return "invalid scientific notation"
    integer = int(match.group(1))
    fraction = match.group(2) or "0"
    exponent = int(match.group(4))
    sign = match.group(3) or "+"
    return f"{sign} {english_number_to_word(integer)} point {fraction} times 10 raised to the power of {exponent}"

def translate_number_to_language(num, lang):
