Here's a Go function that identifies if a given sentence contains a double negative using the approach you described:

```go
package main

import (
	"fmt"
	"strings"
)

func main() {
	sentence := "He isn't not worried about the coronavirus situation"
	negativeWords := []string{"not", "never", "no", "none", "nothing"}

	hasDoubleNegative := checkForDoubleNegative(sentence, negativeWords)

	if hasDoubleNegative {
		fmt.Println("The sentence contains a double negative.")
	} else {
		fmt.Println("The sentence does not contain a double negative.")
	}
}

func checkForDoubleNegative(sentence string, negativeWords []string) bool {
	words := strings.Split(sentence, " ")

	for _, word := range words {
		if containsNegativeWord(word, negativeWords) && containsNotFollowedByNegativeWord(word, negativeWords) {
			return true
		}
	}

	return false
}

func containsNegativeWord(word string, negativeWords []string) bool {
	for _, negativeWord := range negativeWords {
		if word == negativeWord || word == "-" + negativeWord {
			return true
		}
	}

	return false
}

func containsNotFollowedByNegativeWord(word string, negativeWords []string) bool {
	if word == "not" {
		for _, negativeWord := range negativeWords {
			if words[i+1] == negativeWord || words[i+1] == "-" + negativeWord {
				return true
			}
		}
	}

	return false
}
```

This code defines a `checkForDoubleNegative` function that takes a sentence and a slice of negative words as input. It splits the sentence into words, checks if each word is a negative word or contains a negative word followed by "not", and returns `true` if a double negative is found. Otherwise, it returns `false`.

