To push the `portInStatus` variable into the `registrations` state, you can modify the `checkMNPStatusAPI` function like this:

```javascript
checkMNPStatusAPI(phoneNo, index) {
  console.log("mnpphoneno: " + phoneNo);

  var headers = new Headers();
  headers.append("Authorization", "Bearer " + user.getAccessToken());
  fetch(api.checkPortInStatus(user.getProductCode(), phoneNo), {
    headers: headers,
    method: 'GET'
  })
    .then(r => r.json())
    .then(rjson => {
      this.setState(prevState => ({
        registrations: prevState.registrations.map((registration, i) => {
          if (i === index) {
            return { ...registration, portInStatus: rjson.status };
          }
          return registration;
        })
      }));
    });
}
```

